<script lang="ts" module>import type { RxColor } from '$lib/registry/lib/color'; export interface DotStepperProps { current?:number; count:number; color?:RxColor; variant?:'default'|'bars'|'elastic'|'glow'|'ring'|'worm'; orientation?:'horizontal'|'vertical'; labels?:string[]; disabled?:boolean; onCurrentChange?:(index:number)=>void; }</script>
<script lang="ts">import { styleColor } from '$lib/registry/lib/color'; let {current=$bindable(0),count,color,variant='default',orientation='horizontal',labels=[],disabled=false,onCurrentChange}:DotStepperProps=$props(); const safeCount=$derived(Math.max(0,Math.floor(count)));let direction=$state(1);function select(i:number){if(disabled)return;direction=i>=current?1:-1;current=i;onCurrentChange?.(i);}function fidelity(node:HTMLElement){let frame=0;const measure=()=>{cancelAnimationFrame(frame);frame=requestAnimationFrame(()=>{const active=node.querySelector<HTMLElement>('button.active'),ind=node.querySelector<HTMLElement>('.rx-dots__indicator');if(!active||!ind)return;const dot=active.querySelector<HTMLElement>('.rx-dots__dot')!;const x=active.offsetLeft+dot.offsetLeft,y=active.offsetTop+dot.offsetTop;node.style.setProperty('--rx-dot-x',`${x}px`);node.style.setProperty('--rx-dot-y',`${y}px`);node.style.setProperty('--rx-dot-w',`${dot.offsetWidth}px`);node.style.setProperty('--rx-dot-h',`${dot.offsetHeight}px`);node.style.setProperty('--rx-progress-x',`${x+dot.offsetWidth/2}px`);node.style.setProperty('--rx-progress-y',`${y+dot.offsetHeight/2}px`);ind.classList.remove('is-move');void ind.offsetWidth;ind.classList.add('is-ready','is-move')})};const move=(e:PointerEvent)=>{const rect=node.getBoundingClientRect();node.style.setProperty('--rx-mx',`${e.clientX-rect.left}px`);node.style.setProperty('--rx-my',`${e.clientY-rect.top}px`);node.style.setProperty('--rx-lit','1')};const leave=()=>node.style.setProperty('--rx-lit','0');const down=(e:PointerEvent)=>{const button=(e.target as Element).closest<HTMLElement>('button');if(!button)return;const rect=button.getBoundingClientRect(),x=e.clientX-rect.left,y=e.clientY-rect.top;const ripple=document.createElement('i');ripple.className='rx-dots__ripple';ripple.style.cssText=`left:${x}px;top:${y}px`;button.append(ripple);ripple.addEventListener('animationend',()=>ripple.remove(),{once:true})};const ro=new ResizeObserver(measure),mo=new MutationObserver(measure);ro.observe(node);mo.observe(node,{subtree:true,attributes:true,attributeFilter:['class']});node.addEventListener('pointermove',move);node.addEventListener('pointerleave',leave);node.addEventListener('pointerdown',down);measure();return()=>{ro.disconnect();mo.disconnect();node.removeEventListener('pointermove',move);node.removeEventListener('pointerleave',leave);node.removeEventListener('pointerdown',down);cancelAnimationFrame(frame)}};</script>
<nav class="rx-dots rx-dots--{variant} rx-dots--{orientation}" data-direction={direction} aria-label="Progress" style={styleColor(color) ?? '--rx-color: var(--rx-primary)'}><div class="rx-dots__track" style={`--rx-current:${current};--rx-count:${safeCount}`} {@attach fidelity}><span class="rx-dots__progress" aria-hidden="true"></span><span class="rx-dots__indicator" aria-hidden="true"></span>
