<style>@property --rx-ring-spin{syntax:'<angle>';inherits:false;initial-value:0deg}.rx-dots__track{--rx-gap:10px;position:relative;display:flex;align-items:flex-start;gap:var(--rx-gap);isolation:isolate}.rx-dots--vertical .rx-dots__track{flex-direction:column}.rx-dots button{position:relative;z-index:2;overflow:visible;display:grid;justify-items:center;gap:6px;border:0;background:transparent;color:rgb(var(--rx-text-secondary));padding:5px;cursor:pointer}.rx-dots__dot{display:block;width:11px;height:11px;border-radius:999px;background:rgb(var(--rx-border-hover));transition:transform 380ms cubic-bezier(.34,1.56,.64,1),width 380ms cubic-bezier(.34,1.56,.64,1),height 380ms cubic-bezier(.34,1.56,.64,1),background 240ms ease,box-shadow 240ms ease}.rx-dots button:active:not(:disabled) .rx-dots__dot{transform:scale(.8)}.rx-dots button.active .rx-dots__dot{background:rgb(var(--rx-color));transform:scale(1.18)}.rx-dots small{font-size:11px}.rx-dots button:focus-visible{outline:2px solid rgb(var(--rx-color));outline-offset:2px;border-radius:8px}.rx-dots__progress{position:absolute;z-index:0;left:10px;right:10px;top:10px;height:2px;background:rgb(var(--rx-border));overflow:hidden}.rx-dots__progress:after{content:"";position:absolute;left:0;top:0;height:100%;width:calc(var(--rx-progress-x) - 10px);background:rgb(var(--rx-color));transition:width 420ms cubic-bezier(.34,1.4,.64,1)}.rx-dots--vertical .rx-dots__progress{top:10px;bottom:10px;left:10px;right:auto;width:2px;height:auto}.rx-dots--vertical .rx-dots__progress:after{width:100%;height:calc(var(--rx-progress-y) - 10px);transition:height 420ms cubic-bezier(.34,1.4,.64,1)}.rx-dots__indicator{position:absolute;z-index:1;left:0;top:0;width:var(--rx-dot-w,11px);height:var(--rx-dot-h,11px);border-radius:999px;background:rgb(var(--rx-color));opacity:0;transform:translate3d(var(--rx-dot-x,0),var(--rx-dot-y,0),0);transition:transform 380ms cubic-bezier(.34,1.56,.64,1),width 380ms cubic-bezier(.34,1.56,.64,1),height 380ms cubic-bezier(.34,1.56,.64,1),opacity 180ms ease}.rx-dots__indicator.is-ready{opacity:1}:global(.rx-dots__ripple){position:absolute;left:0;top:0;width:26px;height:26px;border-radius:50%;translate:-50% -50%;background:radial-gradient(circle,rgb(var(--rx-color)/.3),transparent 70%);pointer-events:none;animation:rx-dot-ripple 600ms ease-out forwards}
