.rx-dots--glow button.active .rx-dots__dot{box-shadow:0 0 8px rgb(var(--rx-color)/.9),0 0 18px rgb(var(--rx-color)/.55);animation:rx-dot-pulse 1600ms ease-in-out infinite}.rx-dots--glow .rx-dots__indicator{display:none}.rx-dots--glow button.active:before{content:"";position:absolute;left:50%;top:10px;width:30px;height:30px;border-radius:50%;translate:-50% -50%;background:radial-gradient(circle,rgb(var(--rx-color)/.3),transparent 70%);animation:rx-dot-halo 1600ms ease-in-out infinite}.rx-dots--vertical.rx-dots--glow button.active:before{left:10px;top:50%}
.rx-dots--ring button.active .rx-dots__dot{opacity:0}.rx-dots--ring .rx-dots__indicator{padding:2px;background:conic-gradient(from var(--rx-ring-spin,0deg),transparent 0 35deg,rgb(var(--rx-color)) 80deg,transparent 150deg 360deg);mask:linear-gradient(#000 0 0) content-box,linear-gradient(#000 0 0);mask-composite:exclude;animation:rx-dot-ring 2400ms linear infinite}
.rx-dots--worm button .rx-dots__dot{opacity:.28}.rx-dots--worm button.active .rx-dots__dot{opacity:0}.rx-dots--worm .rx-dots__indicator{transform-origin:center;transition:transform 460ms cubic-bezier(.34,1.4,.64,1),width 460ms cubic-bezier(.34,1.4,.64,1),height 460ms cubic-bezier(.34,1.4,.64,1)}.rx-dots--worm[data-direction="1"] :global(.rx-dots__indicator.is-move){animation:rx-worm-next 460ms cubic-bezier(.34,1.4,.64,1)}.rx-dots--worm[data-direction="-1"] :global(.rx-dots__indicator.is-move){animation:rx-worm-prev 460ms cubic-bezier(.34,1.4,.64,1)}
@keyframes rx-dot-ripple{from{transform:scale(0);opacity:.9}to{transform:scale(1);opacity:0}}@keyframes rx-dot-pulse{50%{transform:scale(1.3);box-shadow:0 0 12px rgb(var(--rx-color)),0 0 24px rgb(var(--rx-color)/.65)}}@keyframes rx-dot-halo{50%{transform:scale(1.22);opacity:.45}}@keyframes rx-dot-ring{to{--rx-ring-spin:360deg}}@keyframes rx-worm-next{40%{scale:2.3 1}100%{scale:1}}@keyframes rx-worm-prev{40%{scale:2.3 1}100%{scale:1}}
